public List<Long> primesInRange(long L, long R) {
    // Baseline: only works when R is small enough to allocate R+1 booleans.
    boolean[] composite = new boolean[(int) (R + 1)];
    for (long p = 2; p * p <= R; p++) {
        if (!composite[(int) p]) {
            for (long m = p * p; m <= R; m += p) {
                composite[(int) m] = true;
            }
        }
    }
    List<Long> primes = new ArrayList<>();
    for (long x = Math.max(2, L); x <= R; x++) {
        if (!composite[(int) x]) primes.add(x);
    }
    return primes;
}

