public List<Long> primesInRange(long L, long R) {
    int limit = (int) Math.sqrt((double) R) + 1;
    // Stage 1: plain sieve up to sqrt(R) for the base primes.
    boolean[] isComposite = new boolean[limit + 1];
    List<Integer> basePrimes = new ArrayList<>();
    for (int p = 2; p <= limit; p++) {
        if (!isComposite[p]) {
            basePrimes.add(p);
            for (long m = (long) p * p; m <= limit; m += p) {
                isComposite[(int) m] = true;
            }
        }
    }
    // Stage 2: sieve the window [L, R]; slot i represents number L + i.
    int size = (int) (R - L + 1);
    boolean[] mark = new boolean[size]; // false = still prime
    for (int p : basePrimes) {
        long pp = (long) p * p;
        long firstMultiple = Math.max(pp, ((L + p - 1) / p) * (long) p);
        for (long m = firstMultiple; m <= R; m += p) {
            mark[(int) (m - L)] = true;
        }
    }
    if (L == 1) mark[0] = true; // 1 is not prime, no base prime crosses it out
    List<Long> primes = new ArrayList<>();
    for (int i = 0; i < size; i++) {
        if (!mark[i]) primes.add(L + i);
    }
    return primes;
}

