import math

def primes_in_range(self, L: int, R: int) -> list[int]:
    limit = int(math.isqrt(R)) + 1
    # Stage 1: plain sieve up to sqrt(R) for the base primes.
    is_composite = [False] * (limit + 1)
    base_primes = []
    for p in range(2, limit + 1):
        if not is_composite[p]:
            base_primes.append(p)
            for m in range(p * p, limit + 1, p):
                is_composite[m] = True
    # Stage 2: sieve the window [L, R]; slot i represents number L + i.
    size = R - L + 1
    mark = [False] * size  # False = still prime
    for p in base_primes:
        first_multiple = max(p * p, ((L + p - 1) // p) * p)
        for m in range(first_multiple, R + 1, p):
            mark[m - L] = True
    if L == 1:
        mark[0] = True  # 1 is not prime
    return [L + i for i in range(size) if not mark[i]]

